<?php $tags=[];$base=array_diff_key($f,array_flip(['page','p']));foreach((array)($f['axis']??[]) as $axisKey=>$values){foreach((array)$values as $i=>$value){if($value==='')continue;$labelId=Namira\MartyrTaxonomySchema::ready($db)?Namira\MartyrCatalog::canonical($db,(int)$value):(int)$value;$term=Namira\Db::query($db,'SELECT title FROM protocol_terms WHERE id=?',[$labelId])->fetchColumn();$params=$base;unset($params['axis'][$axisKey][$i]);if(empty($params['axis'][$axisKey]))unset($params['axis'][$axisKey]);$tags[]=['text'=>$term?:'فیلتر','params'=>$params];}}foreach(['country'=>'کشور','province'=>'استان','county'=>'شهرستان','city'=>'شهر'] as $level=>$label){$key='geo_'.$level;if(($f[$key]??'')==='')continue;$value=Namira\Db::query($db,'SELECT title FROM protocol_terms WHERE id=? AND taxonomy=?',[(int)$f[$key],$level])->fetchColumn();$params=$base;unset($params[$key]);$tags[]=['text'=>$label.': '.($value?:'مکان'),'params'=>$params];}foreach(['q'=>'جست‌وجو','year_from'=>'از سال','year_to'=>'تا سال'] as $key=>$label){if(($f[$key]??'')==='')continue;$params=$base;unset($params[$key]);$displayValue=$f[$key];$tags[]=['text'=>$label.': '.$displayValue,'params'=>$params];} ?>
